describe('POST /api/appointments', () => {
  const body = {
    practitionerId: 'pr_rosa',
    startsAt: '2030-01-01T10:00:00.000Z',
    endsAt: '2030-01-01T10:30:00.000Z',
    visitReason: 'SECRET-REASON-xyz',
  };

  it('books and returns 201 with the id only', async () => {
    const res = await call(POST, { method: 'POST', token: TOKENS.ava, body });
    expect(res.status).toBe(201);
    expect(res.json.id).toMatch(/^apt_/);
    expect(res.text).not.toContain('SECRET-REASON');
  });

  it('rejects non-patients, other practices, and non-care-team practitioners', async () => {
    expect((await call(POST, { method: 'POST', token: TOKENS.rosa, body })).status).toBe(403);
    expect((await call(POST, { method: 'POST', token: TOKENS.june, body })).status).toBe(404);
    expect((await call(POST, { method: 'POST', token: TOKENS.ava, body: { ...body, practitionerId: 'pr_malik' } })).status).toBe(403);
    expect((await call(POST, { method: 'POST', body })).status).toBe(401);
  });

  it('unexpected failure: errorId in body, one log line with cause, no PHI', async () => {
    const out: string[] = [];
    const o = vi.spyOn(process.stdout, 'write').mockImplementation((s: any) => (out.push(String(s)), true));
    const e = vi.spyOn(process.stderr, 'write').mockImplementation((s: any) => (out.push(String(s)), true));
    const repo = await import('@/repos/appointments');
    const spy = vi.spyOn(repo, 'createAppointment').mockRejectedValue(
      Object.assign(new Error("Unknown column; values SECRET-REASON-xyz"), {
        code: 'ER_BAD_FIELD_ERROR',
        sql: 'INSERT ... SECRET-REASON-xyz',
        sqlMessage: 'SECRET-REASON-xyz',
      }),
    );
    const res = await call(POST, { method: 'POST', token: TOKENS.ava, body });
    spy.mockRestore();
    o.mockRestore();
    e.mockRestore();
    expect(res.status).toBe(500);
    expect(res.json.errorId).toMatch(/^err_/);
    expect(Object.keys(res.json)).toEqual(['errorId']);
    const lines = out.filter((l) => l.includes(res.json.errorId));
    expect(lines).toHaveLength(1);
    const line = JSON.parse(lines[0]);
    expect(line.route).toBe('POST /api/appointments');
    expect(line.cause.code).toBe('ER_BAD_FIELD_ERROR');
    const all = out.join('');
    for (const s of ['SECRET-REASON', 'INSERT', 'Ava', 'ava@']) expect(all).not.toContain(s);
  });
});
